                "partyBehind": {
                  "id": "watchers.b.beginning.battle.partyBehind",
                  "speaker": "Bren",
                  "speakerId": "bren",
                  "text": "Count slowly. The colony sees paths that disappear when you look only at the largest piece.",
                  "delivery": "Quiet support beside the player; leave room for the opponent.",
                  "voiceId": "watchers.b.beginning.battle.partyBehind"
                },
