      "outro": [
        {
          "id": "zoroark.outro.original-001",
          "speaker": "Narrator",
          "speakerId": "narrator",
          "text": "The recovered trace is copied under Toma’s supervision. Galactic’s latest offer names a 2020 staging realm and a route toward the origin site.",
          "delivery": "Observe physical details; allow silence.",
          "voiceId": "zoroark.outro.original-001.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.outro.original-002",
          "speaker": "Celebi",
          "speakerId": "celebi",
          "text": "I thought I would recognize myself when it came back.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.outro.original-002.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.toma-separate-copies.01",
          "speaker": "You",
          "speakerId": "player",
          "text": "Do you?",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.toma-separate-copies.01.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.toma-separate-copies.02",
          "speaker": "Celebi",
          "speakerId": "celebi",
          "text": "I recognize being certain I could reach him. It is embarrassing. I wanted that person to have a better plan.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.toma-separate-copies.02.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.toma-separate-copies.03",
          "speaker": "Neri",
          "speakerId": "neri",
          "text": "You also stayed for the last boats. Maren remembers that person.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.toma-separate-copies.03.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.toma-separate-copies.04",
          "speaker": "Celebi",
          "speakerId": "celebi",
          "text": "I am trying to fit them together.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.toma-separate-copies.04.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.toma-separate-copies.05",
          "speaker": "Narrator",
          "speakerId": "narrator",
          "text": "Toma threads the copied pages. One knot refuses to tighten; he swears at it under his breath.",
          "delivery": "Observe physical details; allow silence.",
          "voiceId": "zoroark.toma-separate-copies.05.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.1",
          "speaker": "You",
          "speakerId": "player",
          "text": "There. You have something in common.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.1.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.2",
          "speaker": "Celebi",
          "speakerId": "celebi",
          "text": "I am considerably more polite to knots.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.2.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.3",
          "speaker": "Toma",
          "speakerId": "toma",
          "text": "Then I shall remember you as a judgmental client.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.3.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.4",
          "speaker": "Narrator",
          "speakerId": "narrator",
          "text": "Neri must return to warn Newbank. She presses Maren’s empty food tin into your hand.",
          "delivery": "Observe physical details; allow silence.",
          "voiceId": "zoroark.farewell.depth3.4.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.5",
          "speaker": "Neri",
          "speakerId": "neri",
          "text": "Bring it back. She counts them.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.5.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.6",
          "speaker": "Celebi",
          "speakerId": "celebi",
          "text": "Rowan keeps sending sweet berries. I do not like them very much.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.6.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.7",
          "speaker": "Neri",
          "speakerId": "neri",
          "text": "An alarming revelation. Shall we tell him?",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.7.r4",
          "locationArea": 1
        },
        {
          "id": "zoroark.farewell.depth3.8",
          "speaker": "Celebi",
          "speakerId": "celebi",
          "text": "Not yet. I want to tell him myself, when we call.",
          "delivery": "Speak to the person present; let hesitation, anger or affection remain in the line.",
          "voiceId": "zoroark.farewell.depth3.8.r4",
          "locationArea": 1
        }
      ],
