              "signatureExchanges": {
                "signature1": {
                  "attack": "Flare Strike",
                  "lines": [
                    {
                      "id": "together.b.enough.battle.signature1",
                      "speaker": "Reshiram & Charizard",
                      "speakerId": "reshiram-charizard",
                      "text": "A strong flame needs someone willing to stand beside it.",
                      "delivery": "React to the confirmed battle event; do not interrupt play.",
                      "voiceId": "together.b.enough.battle.signature1"
                    },
                    {
                      "id": "together.b.enough.exchange.signature1.1",
                      "speaker": "Celebi",
                      "speakerId": "celebi",
                      "text": "How do you know when to give everything and when to let someone else help?",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature1.1"
                    },
                    {
                      "id": "together.b.enough.exchange.signature1.2",
                      "speaker": "Reshiram & Charizard",
                      "speakerId": "reshiram-charizard",
                      "text": "We ask each other before the flame gets that high.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature1.2"
                    },
                    {
                      "id": "together.b.enough.exchange.signature1.3",
                      "speaker": "Jun",
                      "speakerId": "jun",
                      "text": "Then we should practice asking while there is still time to hear the answer.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature1.3"
                    },
                    {
                      "id": "together.b.enough.exchange.signature1.4",
                      "speaker": "Reshiram & Charizard",
                      "speakerId": "reshiram-charizard",
                      "text": "Exactly. Help is easier to offer before it becomes a rescue.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature1.4"
                    }
                  ]
                },
                "signature2": {
                  "attack": "Double Blaze-GX",
                  "lines": [
                    {
                      "id": "together.b.enough.battle.signature2",
                      "speaker": "Reshiram & Charizard",
                      "speakerId": "reshiram-charizard",
                      "text": "We chose this moment together. That is why neither of us has to hold back.",
                      "delivery": "React to the confirmed battle event; do not interrupt play.",
                      "voiceId": "together.b.enough.battle.signature2"
                    },
                    {
                      "id": "together.b.enough.exchange.signature2.1",
                      "speaker": "Celebi",
                      "speakerId": "celebi",
                      "text": "You were both ready. I thought courage was one person going first.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature2.1"
                    },
                    {
                      "id": "together.b.enough.exchange.signature2.2",
                      "speaker": "Reshiram & Charizard",
                      "speakerId": "reshiram-charizard",
                      "text": "Sometimes it is making sure your partner is ready to go with you.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature2.2"
                    },
                    {
                      "id": "together.b.enough.exchange.signature2.3",
                      "speaker": "Jun",
                      "speakerId": "jun",
                      "text": "We will ask before we step into the anchor. Nobody gets carried past their own answer.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature2.3"
                    },
                    {
                      "id": "together.b.enough.exchange.signature2.4",
                      "speaker": "Reshiram & Charizard",
                      "speakerId": "reshiram-charizard",
                      "text": "Then you understand why we waited for this moment.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "together.b.enough.exchange.signature2.4"
                    }
                  ]
                }
              }
